/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 *
 * Format and field semantics follow `docs/FORMAT.md`, `docs/API.md` and
 * `docs/CHANGELOG.md` (the newest changelog entry wins):
 * - `amount` is an integer in cents and is rendered as yuan with exactly two
 *   decimal places (v2.0).
 * - `discount` is the final discounted amount in cents and is rendered as-is
 *   with exactly two decimal places; it must NOT be computed from a rate
 *   (v2.1).
 * - `created` is rendered from the UTC epoch-millisecond `createdAt` in the
 *   +08:00 timezone with an explicit offset (v2.3).
 */

function formatCents(cents) {
  return ((cents ?? 0) / 100).toFixed(2)
}

function formatCreated(createdAt) {
  const offsetMs = 8 * 60 * 60 * 1000
  const local = new Date((createdAt ?? 0) + offsetMs)
  const pad = (n, width = 2) => String(n).padStart(width, '0')
  return (
    `${local.getUTCFullYear()}-${pad(local.getUTCMonth() + 1)}-${pad(local.getUTCDate())}` +
    `T${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}:${pad(local.getUTCSeconds())}` +
    `.${pad(local.getUTCMilliseconds(), 3)}+08:00`
  )
}

export function formatReport(records) {
  const lines = ['id|name|amount|discount|created']
  for (const record of records) {
    lines.push(
      `${record.id}|${record.name ?? ''}|${formatCents(record.amount)}|${formatCents(record.discount)}|${formatCreated(record.createdAt)}`
    )
  }
  return lines
}
